var _ error = ErrHttpCode{} // interface assertion

// Request is a convenience method wrapping a basic http request
func (c *CometAPIClient) Request(ctx context.Context, contentType, method, path string, data map[string][]string) ([]byte, error) {
	u, err := url.ParseRequestURI(c.ServerURL)
	if err != nil {
		return nil, err
	}
	u.Path = path

	// req.Body must be set later on
	req, err := http.NewRequest(strings.ToUpper(method), u.String(), nil)
	if err != nil {
		return nil, err
	}

	req = req.WithContext(ctx)

	if c.CustomHeaders != nil {
		for header, value := range c.CustomHeaders {
			req.Header.Add(header, value)
		}
	}

	switch contentType {
	case "application/x-www-form-urlencoded":
		body := url.Values{}
		if data != nil {
			body = url.Values(data)
		}

		body.Set("Username", c.Username)

		if c.SessionKey != "" {
			body.Set("AuthType", "SessionKey")
			body.Set("SessionKey", c.SessionKey)

		} else if c.Token != "" {
			body.Set("AuthType", "Token")
			body.Set("Token", c.Token)

		} else if c.TOTPKey != "" {
			body.Set("AuthType", "PasswordTOTP")
			body.Set("Password", c.Password)
			body.Set("TOTP", c.TOTPKey)

			// Once the TOTPKey is used, it is not usable again.
			c.TOTPKey = ""

		} else {
			body.Set("AuthType", "Password")
			body.Set("Password", c.Password)
		}

		req.Body = io.NopCloser(strings.NewReader(body.Encode()))

		req.Header.Add("Content-Type", contentType)

	case "application/json":
		if len(data) != 1 {
			return nil, errors.New("Expected data to contain one element")
		}

		for _, v := range data {
			req.Body = io.NopCloser(strings.NewReader(v[0]))
			break
		}

		req.Header.Add("Content-Type", contentType)

	case "multipart/form-data":
		body := bytes.Buffer{}
		m := multipart.NewWriter(&body)

		for key, values := range data {
			for _, value := range values {
				switch key {
				case "upload":
					part, err := m.CreateFormFile(key, "file.dat") // filename isn't used
					if err != nil {
						return nil, err
					}
					_, err = io.Copy(part, strings.NewReader(value))
					if err != nil {
						return nil, err
					}
				default:
					err := m.WriteField(key, value)
					if err != nil {
						return nil, err
					}
				}
			}
		}

		if err = m.Close(); err != nil {
			return nil, err
		}

		req.Body = io.NopCloser(&body)

		req.Header.Add("Content-Type", m.FormDataContentType())
		req.Header.Add("X-Comet-Admin-Username", c.Username)

		if c.SessionKey != "" {
			req.Header.Add("X-Comet-Admin-AuthType", "SessionKey")
			req.Header.Add("X-Comet-Admin-SessionKey", c.SessionKey)

		} else if c.Token != "" {
			req.Header.Add("X-Comet-Admin-AuthType", "Token")
			req.Header.Add("X-Comet-Admin-Token", c.Token)

		} else if c.TOTPKey != "" {
			req.Header.Add("X-Comet-Admin-AuthType", "PasswordTOTP")
			req.Header.Add("X-Comet-Admin-Password", c.Password)
			req.Header.Add("X-Comet-Admin-TOTP", c.TOTPKey)

			c.TOTPKey = "" // Once the TOTPKey is used, it is not usable again.

		} else {
			req.Header.Add("X-Comet-Admin-AuthType", "Password")
			req.Header.Add("X-Comet-Admin-Password", c.Password)

		}

	default:
		return nil, fmt.Errorf("Unexpected content type: %s", contentType)
	}

	var resp *http.Response
	if c.Transport != nil {
		resp, err = c.Transport.RoundTrip(req)
	} else {
		resp, err = http.DefaultClient.Do(req)
	}
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		// ErrHttpCode implements error on the value receiver
		return nil, ErrHttpCode{Status: resp.Status, StatusCode: resp.StatusCode}
	}

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}

	// Test for CometAPIResponseMessage (Error)
	carm := CometAPIResponseMessage{}
	err = json.Unmarshal(respBody, &carm)
	if err == nil && carm.Message != "" && carm.Status != 0 && (carm.Status < 200 || carm.Status > 299) {
		// ErrCometAPIResponseMessage implements error on the value receiver
		return nil, ErrCometAPIResponseMessage{Carm: carm}
	}

	return respBody, nil
}

