// HybridSessionStart: Generate a session key (log in)
// This hybrid API allows you to log in to the Comet Server as either an administrator or end-user
// account.
// This API behaves like either AdminAccountSessionStart or UserWebSessionStart, depending on what
// the supplied credentials were valid for.
//
// This API does not accept admin personal API token authentication (AuthType=Token, or the token
// supplied as the password with AuthType=Password).
//
// The SessionKey will be set in the client and used for any further api calls using the same client.
// You can manually clear the SessionKey if you wish to use Username, Password based authentication again.
func (c *CometAPIClient) HybridSessionStart(ctx context.Context) (*SessionKeyRegeneratedResponse, error) {
	body, err := c.Request(ctx, "application/x-www-form-urlencoded", "POST", "/api/v1/hybrid/session/start", nil)
	if err != nil {
		return nil, err
	}

	result := &SessionKeyRegeneratedResponse{}
	err = json.Unmarshal(body, &result)
	if err != nil {
		return nil, err
	}

	if c.ReuseSessionKey {
		// Set the SessionKey so that future invocations use the SessionKey.
		c.SessionKey = result.SessionKey
	}

	return result, nil
}

